package com.aistock.market.security;
import com.fasterxml.jackson.databind.ObjectMapper;import com.fasterxml.jackson.databind.SerializationFeature;import java.time.Clock;import org.springframework.context.annotation.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.web.servlet.FilterRegistrationBean;
@Configuration public class MarketSecurityConfiguration {
 @Bean Clock marketClock(){return Clock.systemUTC();}
 @Bean ObjectMapper marketMapper(){return new ObjectMapper().findAndRegisterModules().disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);}
 @Bean FilterRegistrationBean<MarketAccessFilter> marketAccess(SessionIdentityClient client,@Value("${aistock.internal.token:}")String token,ObjectMapper mapper){var bean=new FilterRegistrationBean<>(new MarketAccessFilter(client,token,mapper));bean.setOrder(-90);bean.addUrlPatterns("/api/v1/instruments","/api/v1/instruments/*");return bean;}
 @Bean FilterRegistrationBean<com.aistock.market.statistics.AdminStatisticsAccessFilter> statisticsAccess(SessionIdentityClient client,@Value("${aistock.internal.token:}")String token,ObjectMapper mapper){var b=new FilterRegistrationBean<>(new com.aistock.market.statistics.AdminStatisticsAccessFilter(client,token,mapper));b.setOrder(-90);b.addUrlPatterns("/api/v1/admin/statistics","/api/v1/admin/statistics/*");return b;}
 @Bean FilterRegistrationBean<org.springframework.web.filter.CorsFilter> statisticsCors(@Value("${aistock.auth.allowed-origins:http://127.0.0.1:15173,http://localhost:15173}")String origins){var c=new org.springframework.web.cors.CorsConfiguration();c.setAllowedOrigins(java.util.Arrays.stream(origins.split(",")).map(String::strip).toList());c.setAllowCredentials(true);c.setAllowedMethods(java.util.List.of("GET","OPTIONS"));c.setAllowedHeaders(java.util.List.of("Content-Type","X-Trace-Id"));var source=new org.springframework.web.cors.UrlBasedCorsConfigurationSource();source.registerCorsConfiguration("/api/v1/admin/statistics/market",c);var b=new FilterRegistrationBean<>(new org.springframework.web.filter.CorsFilter(source));b.setOrder(-100);b.addUrlPatterns("/api/v1/admin/statistics","/api/v1/admin/statistics/*");return b;}

 @Bean FilterRegistrationBean<com.aistock.market.adminquery.AdminMarketDataAccessFilter> adminMarketDataAccess(SessionIdentityClient client,@Value("${aistock.internal.token:}")String token,ObjectMapper mapper,@Value("${aistock.auth.allowed-origins:http://127.0.0.1:15173,http://localhost:15173}")String origins){var b=new FilterRegistrationBean<>(new com.aistock.market.adminquery.AdminMarketDataAccessFilter(client,token,mapper,origins));b.setOrder(-90);b.addUrlPatterns("/api/v1/admin/market-data","/api/v1/admin/market-data/*");return b;}
 @Bean FilterRegistrationBean<org.springframework.web.filter.CorsFilter> adminMarketDataCors(@Value("${aistock.auth.allowed-origins:http://127.0.0.1:15173,http://localhost:15173}")String origins){var c=new org.springframework.web.cors.CorsConfiguration();c.setAllowedOrigins(java.util.Arrays.stream(origins.split(",")).map(String::strip).toList());c.setAllowCredentials(true);c.setAllowedMethods(java.util.List.of("GET","OPTIONS"));c.setAllowedHeaders(java.util.List.of("Content-Type","X-Trace-Id"));var source=new org.springframework.web.cors.UrlBasedCorsConfigurationSource();source.registerCorsConfiguration("/api/v1/admin/market-data",c);source.registerCorsConfiguration("/api/v1/admin/market-data/*/versions",c);source.registerCorsConfiguration("/api/v1/admin/market-data/*/versions/*",c);source.registerCorsConfiguration("/api/v1/admin/market-data/*/versions/*/references",c);var review=new org.springframework.web.cors.CorsConfiguration(c);review.setAllowedMethods(java.util.List.of("GET","POST","OPTIONS"));review.setAllowedHeaders(java.util.List.of("Content-Type","X-Trace-Id","X-Aistock-Admin-Action"));source.registerCorsConfiguration("/api/v1/admin/market-data/*/versions/*/reviews",review);source.registerCorsConfiguration("/api/v1/admin/market-data/*/versions/*/reviews/*",c);
  source.registerCorsConfiguration("/api/v1/admin/market-data/*/versions/*/lifecycle/actions",review);
  source.registerCorsConfiguration("/api/v1/admin/market-data/*/versions/*/lifecycle/actions/*",c);
  var b=new FilterRegistrationBean<org.springframework.web.filter.CorsFilter>(new org.springframework.web.filter.CorsFilter(source){@Override protected void doFilterInternal(jakarta.servlet.http.HttpServletRequest r,jakarta.servlet.http.HttpServletResponse response,jakarta.servlet.FilterChain chain)throws java.io.IOException,jakarta.servlet.ServletException{response.setHeader("Cache-Control","no-store");super.doFilterInternal(r,response,chain);}});b.setOrder(-100);b.addUrlPatterns("/api/v1/admin/market-data","/api/v1/admin/market-data/*");return b;}
}
